pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract SafeTransferRecipient {
    C public immutable pool;
    bool public received;
    bytes4 public returnedSelector;

    constructor(C _pool) {
        pool = _pool;
    }

    function onERC721Received(
        address,
        address from,
        uint256,
        bytes calldata
    ) external returns (bytes4) {
        // Call back into the pool to observe the return value of the pool's onERC721Received
        // by triggering a safeTransferFrom from within the callback context.
        // This simulates an external party that checks the returned selector.
        try pool.onERC721Received(address(0), from, 0, "") returns (bytes4 sel) {
            returnedSelector = sel;
            received = true;
        } catch {
            received = false;
        }
        // Return the canonical selector so the current safeTransferFrom succeeds
        return 0x150b7a02;
    }

    // Helper to execute the test flow
    function trigger(address token, uint256 tokenId) external {
        // safeTransferFrom to this contract will call onERC721Received
        ERC721(token).safeTransferFrom(msg.sender, address(this), tokenId);
    }
}

interface ERC721 {
    function safeTransferFrom(address from, address to, uint256 tokenId) external;
    function safeTransferFrom(address from, address to, uint256 tokenId, bytes calldata data) external;
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(uint256 tokenId) public {
        // Any tokenId is admissible
        // Deploy the adversarial recipient that will observe c's onERC721Received return
        SafeTransferRecipient recipient = new SafeTransferRecipient(c);
        // The call to onERC721Received from within recipient observes c.onERC721Received
        // and stores the returned selector.
        // We need to trigger the flow: recipient.trigger -> safeTransferFrom -> onERC721Received (recipient)
        // -> calls c.onERC721Received -> stores result.
        // For this we need an ERC721 token that exists. Use the c's nft? But c is an ERC721TokenReceiver,
        // not an ERC721. We'll use a mock ERC721 that actually calls onERC721Received. But the adversarial rule
        // says we can deploy a helper. We create a minimal ERC721 that does safeTransferFrom and calls onERC721Received.
        // But wait: the adversarial counterparty requirement is about external party that FAILS/REVERTS.
        // Here the difference is in the return value of c.onERC721Received. We can call it directly.
        // The bug is simply that c.onERC721Received returns 0xdeadbeef instead of 0x150b7a02.
        // We can assert that directly: assertEq(c.onERC721Received(address(0), address(0), 0, ""), bytes4(0x150b7a02));
        // But we need a general rule and fuzz params.
        // The rule: For any input, c.onERC721Received returns the correct ERC721TokenReceiver selector.
        // Fuzz params: address a, address b, uint256 cId, bytes calldata data

        // We can directly call c.onERC721Received with fuzzed arguments and check the return value.
        // The reference returns 0x150b7a02 for any input. The mutant returns 0xdeadbeef for any input.
        // So the assertion is: c.onERC721Received(...) == 0x150b7a02.
        // But we need exactly one assertTrue. We can do assertTrue(c.onERC721Received(...) == 0x150b7a02).

        // Since onERC721Received is external view? No, it's not view, but it doesn't modify state, it just returns a constant.
        // It's external, so we can call it.

        bytes memory data = abi.encode(tokenId); // fuzz data
        bytes4 returned = c.onERC721Received(address(0), address(0), tokenId, data);
        assertTrue(returned == 0x150b7a02);
    }
}

