pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee) public {
        // initialization must happen exactly once; we provide admissible dummy values for the other parameters
        // and use the fuzzed _changeFee as the intended changeFee.
        // The general rule: after a successful initialize call, c.changeFee() must equal the supplied _changeFee.

        // Prevent revert due to feeRateTooHigh
        uint16 feeRate = 1000;
        // Provide empty merkleRoot (not used), oracles/pay flags false
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        // virtual reserves can be any non-zero; we set them to 1e18 so they are nonzero
        uint128 virtualBaseTokenReserves = 1e18;
        uint128 virtualNftReserves = 1e18;

        // Prank a caller so that initialize() runs. The caller must be a non-zero address.
        address caller = address(1);
        vm.prank(caller);
        // initialize requires that the sender is the owner of the NFT (minted to the factory which we passed as address(this) in setUp).
        // However, c is a minimal deployment and not owned by anyone initially. In the reference flow, the Factory mints the NFT to the initial caller before calling initialize.
        // To avoid the Unauthorized revert, we need to make the caller the owner of the token that represents this C instance.
        // The tokenId is uint160(address(c)). We'll just set up the authorized path correctly.
        // The onlyOwner modifier uses Factory(factory).ownerOf(uint160(address(this))). We control the factory (address(this)), so we can mint the token to the caller.
        // Since factory is address(this) in setUp, we can call the ERC721 _mint on the factory. But the factory we deployed is a 'C' mock, not the real Factory.
        // Actually C's constructor sets factory to the first argument, which is address(this). So factory == address(this). address(this) is the InvMutTest, which does not implement ownerOf.
        // To avoid complexity, we can skip the onlyOwner requirement by making the caller the owner of the token. We'll set up the test so that the factory (address(this)) returns the caller as owner.
        // Since InvMutTest doesn't have ownerOf, we can use an adversarial approach: we deploy a minimal factory stub that returns the expected owner for the token.
    }
}

// The Factory must implement ownerOf to return the caller. We deploy a minimal stub.
contract FactoryStub {
    mapping(uint256 => address) public ownerOf;
    function setOwner(uint256 tokenId, address owner) external {
        ownerOf[tokenId] = owner;
    }
}

